/**
 * Generates `src/environments/firebase.config.ts` from environment variables.
 *
 * Locally the values come from `.env` (see `.env.example`); in CI they come
 * from GitHub secrets. Both `.env` and the generated file are git-ignored, so
 * the Firebase keys never land in the repository. Fails the build when a value
 * is missing, so a deploy can never ship a contact form that cannot save.
 *
 * Usage: `node scripts/firebase-config.mjs` (runs before start/build/test).
 */
import {existsSync, writeFileSync} from 'node:fs';

/** Maps each generated config property to the environment variable holding it. */
const VARIABLES = {
  apiKey: 'FIREBASE_API_KEY',
  authDomain: 'FIREBASE_AUTH_DOMAIN',
  projectId: 'FIREBASE_PROJECT_ID',
  storageBucket: 'FIREBASE_STORAGE_BUCKET',
  messagingSenderId: 'FIREBASE_MESSAGING_SENDER_ID',
  appId: 'FIREBASE_APP_ID',
};

/** Path of the generated TypeScript module. */
const OUTPUT = 'src/environments/firebase.config.ts';

if (existsSync('.env')) {
  process.loadEnvFile('.env');
}

const missing = Object.values(VARIABLES).filter(name => !process.env[name]?.trim());
if (missing.length) {
  console.error(`firebase-config: missing ${missing.join(', ')}. Fill them in .env (see .env.example) or as CI secrets.`);
  process.exit(1);
}

const entries = Object.entries(VARIABLES)
  .map(([key, name]) => `  ${key}: ${JSON.stringify(process.env[name].trim())},`)
  .join('\n');

writeFileSync(OUTPUT, `// Generated by scripts/firebase-config.mjs from .env or CI secrets. Do not edit or commit.

/** Firebase web-app configuration, shared by every domain build. */
export const firebaseConfig = {
${entries}
};
`);
console.log(`firebase-config: wrote ${OUTPUT}`);
